sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float speed;
uniform float intensity;
uniform float seed;
float hash21(float2 p)
{
    p = fract(p * float2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}
half4 main(float2 coord)
{
    half4 c = image.eval(coord);
    if (c.a <= 0.001 || speed <= 0.0 || intensity <= 0.0) return c;
    float f = time * speed;
    float n = floor(f);
    float ramp = 0.15;
    float t = clamp((f - n - (1.0 - ramp)) / ramp, 0.0, 1.0);
    float r = mix(hash21(float2(n, seed)), hash21(float2(n + 1.0, seed)), t);
    float keep = clamp(1.0 - intensity * r, 0.0, 1.0);
    return c * half(keep);
}
